import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

async function main() {
  const oldId = '6a042d45d5dbce46985514a9';
  const newId = '6a2e6b4883c3e02206dbf2d7'; // SK ENTERPRISE

  console.log(`=== Starting Database Migration/Restoration ===`);
  console.log(`From Distributor ID (Old/Deleted): ${oldId}`);
  console.log(`To Distributor ID (New): ${newId}`);

  // 1. Update Products
  const productsUpdated = await prisma.product.updateMany({
    where: { distributorId: oldId },
    data: { distributorId: newId }
  });
  console.log(`Updated ${productsUpdated.count} products successfully.`);

  // 2. Update Orders
  const ordersUpdated = await prisma.order.updateMany({
    where: { distributorId: oldId },
    data: { distributorId: newId }
  });
  console.log(`Updated ${ordersUpdated.count} orders successfully.`);

  // 3. Create active connections for the shopkeepers who ordered from this distributor
  const shopkeepersData = [
    {
      id: '6a044a56d5dbce46985514d5',
      shopkeeperName: 'Aarifh',
      shopName: 'Rangrej',
      phone: '0000000000'
    },
    {
      id: '6a072708ba487f9a4012b7a5',
      shopkeeperName: 'Mohit Saini',
      shopName: 'Mk',
      phone: '7849945852'
    },
    {
      id: '6a126b58f87a13634bf961d9',
      shopkeeperName: 'aman sharma',
      shopName: 'Sharma General Store',
      phone: '7627047702'
    }
  ];

  const distProfile = await prisma.distributorProfile.findUnique({
    where: { id: newId }
  });

  if (!distProfile) {
    throw new Error(`Target distributor profile ${newId} not found!`);
  }

  for (const sk of shopkeepersData) {
    // Check if connection already exists
    const existingConnection = await prisma.connection.findFirst({
      where: {
        shopkeeperId: sk.id,
        distributorId: newId
      }
    });

    if (existingConnection) {
      console.log(`Connection already exists between ${sk.shopkeeperName} (${sk.shopName}) and ${distProfile.businessName}. Updating status to active.`);
      await prisma.connection.update({
        where: { id: existingConnection.id },
        data: { status: 'active' }
      });
    } else {
      console.log(`Creating active connection between ${sk.shopkeeperName} (${sk.shopName}) and ${distProfile.businessName}.`);
      await prisma.connection.create({
        data: {
          shopkeeperId: sk.id,
          shopkeeperName: sk.shopkeeperName,
          shopName: sk.shopName,
          distributorId: newId,
          distributorName: distProfile.ownerName || '',
          businessName: distProfile.businessName,
          status: 'active',
          shopkeeperPhone: sk.phone
        }
      });
    }
  }

  console.log(`=== Migration/Restoration Completed Successfully ===`);
}

main()
  .catch(e => {
    console.error('Migration failed:', e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
